import json

task = json.load(open('task.json'))
parts = task['parts']

# Compute bottom_z and top_z for each part
for p in parts:
    p['bottom_z'] = p['target_position'][2] - p['size_m'][2] / 2
    p['top_z'] = p['target_position'][2] + p['size_m'][2] / 2
    p['x_min'] = p['target_position'][0] - p['size_m'][0] / 2
    p['x_max'] = p['target_position'][0] + p['size_m'][0] / 2
    p['y_min'] = p['target_position'][1] - p['size_m'][1] / 2
    p['y_max'] = p['target_position'][1] + p['size_m'][1] / 2

TOL = 1e-4

def overlaps_2d(a, b):
    """Check if 2D footprints overlap with strict interior (both axes)."""
    x_overlap = min(a['x_max'], b['x_max']) - max(a['x_min'], b['x_min'])
    y_overlap = min(a['y_max'], b['y_max']) - max(a['y_min'], b['y_min'])
    return x_overlap > 1e-6 and y_overlap > 1e-6

# Part j supports part i if j.top_z ~= i.bottom_z AND footprints overlap
# Build dependency: i depends on j (j must be placed before i)
deps = {i: set() for i in range(len(parts))}
for i in range(len(parts)):
    for j in range(len(parts)):
        if i == j:
            continue
        if abs(parts[j]['top_z'] - parts[i]['bottom_z']) < TOL:
            if overlaps_2d(parts[i], parts[j]):
                deps[i].add(j)

# Topological sort (Kahn's)
in_degree = {i: len(deps[i]) for i in range(len(parts))}
from collections import defaultdict, deque
dependents = defaultdict(set)
for i, ds in deps.items():
    for j in ds:
        dependents[j].add(i)

queue = deque([i for i in range(len(parts)) if in_degree[i] == 0])
order = []
while queue:
    # Sort by bottom_z for stability
    queue = deque(sorted(queue, key=lambda x: (parts[x]['bottom_z'], x)))
    node = queue.popleft()
    order.append(node)
    for d in dependents[node]:
        in_degree[d] -= 1
        if in_degree[d] == 0:
            queue.append(d)

print(f"Placed {len(order)}/{len(parts)} parts in topological order")
print("Order:")
for idx in order:
    p = parts[idx]
    print(f"  Part {idx}: pos=({p['target_position'][0]:.3f}, {p['target_position'][1]:.3f}, {p['target_position'][2]:.3f}), size={p['size_m']}, bottom_z={p['bottom_z']:.4f}, deps={sorted(deps[idx])}")

